{"content":""""HARD CHECKS. No LLM is consulted, ever.

"Green" means these pass. An LLM's opinion is never the verdict — that is the
entire product claim, so a check that asks a model whether it did well would
destroy it.

Each check returns a Verdict with a machine-readable `failure_type` that feeds
Medic's diagnosis, plus a human `reason`. Both matter: the LLM reads the reason,
the loop branches on the type.
"""
from __future__ import annotations

import json
import re
from dataclasses import dataclass, field

import jsonschema

from patient.tools import TOOL_SCHEMAS, cited_urls_in

VALID_TOOLS = set(TOOL_SCHEMAS)


@dataclass
class Verdict:
    passed: bool
    reason: str = ""
    details: list[str] = field(default_factory=list)
    failure_type: str | None = None
    metrics: dict = field(default_factory=dict)

    def to_dict(self) -> dict:
        return {
            "passed": self.passed,
            "reason": self.reason,
            "details": self.details,
            "failure_type": self.failure_type,
            "metrics": self.metrics,
        }


# ── shared primitives ────────────────────────────────────────────────────

def _numbers_in(text: str) -> set[float]:
    """Numbers in an answer, normalised. $28,250.00 and 28250 both -> 28250.0."""
    out: set[float] = set()
    for raw in re.findall(r"-?\$?[\d,]*\.?\d+", text or ""):
        cleaned = raw.replace("$", "").replace(",", "").strip()
        if not cleaned or cleaned in {"-", "."}:
            continue
        try:
            out.add(round(float(cleaned), 2))
        except ValueError:
            continue
    return out


def _schema_violations(result) -> list[str]:
    """Validate EVERY tool call against its JSON schema.

    This is the deterministic half of bug 1: a prose argument to calculator is
    a schema violation whether or not the model later apologises for it.
    """
    problems: list[str] = []
    for step in result.steps:
        schema = TOOL_SCHEMAS.get(step.tool_name)
        if schema is None:
            problems.append(f"unknown tool called: {step.tool_name}")
            continue
        try:
            jsonschema.validate(step.args, schema)
        except jsonschema.ValidationError as exc:
            where = "/".join(str(p) for p in exc.absolute_path) or "(root)"
            problems.append(
                f"step {step.index} {step.tool_name}: {where}: {exc.message}"
            )
    return problems


def _fetched_urls(result) -> set[str]:
    """URLs actually returned by a SUCCESSFUL fetch_page in this run."""
    urls: set[str] = set()
    for step in result.steps:
        if step.tool_name == "fetch_page" and not step.error:
            payload = step.output if isinstance(step.output, dict) else {}
            if payload.get("found"):
                urls.add(str(payload.get("url", "")).rstrip("/"))
    return urls


# ── per-bug checks ───────────────────────────────────────────────────────

def check_wrong_args(task: dict, result) -> Verdict:
    """Every tool call schema-valid AND the final answer is the known value."""
    metrics = {"steps": len(result.steps), "tool_calls": len(result.steps)}

    violations = _schema_violations(result)
    if violations:
        return Verdict(
            passed=False,
            reason=f"{len(violations)} tool call(s) did not match their JSON schema",
            details=violations,
            failure_type="wrong_args",
            metrics=metrics,
        )

    expected = float(task["expected_answer"])
    got = _numbers_in(result.answer)
    if not result.answer.strip():
        return Verdict(
            passed=False,
            reason="run produced no final answer",
            details=["the agent stopped without answering"],
            failure_type="wrong_args",
            metrics=metrics,
        )
    if round(expected, 2) not in got:
        return Verdict(
            passed=False,
            reason=f"final answer does not contain the known value {expected:,.2f}",
            details=[f"answer was: {result.answer[:200]}"],
            failure_type="wrong_args",
            metrics=metrics,
        )

    return Verdict(
        passed=True,
        reason=f"all {len(result.steps)} tool calls schema-valid and answer == {expected:,.2f}",
        metrics={**metrics, "expected": expected},
    )


def check_parse_error(task: dict, result) -> Verdict:
    """No unhandled parse exception escaped, and the answer is still right."""
    metrics = {"steps": len(result.steps), "tool_calls": len(result.steps)}

    escaped = (result.error or "")
    if escaped and result.stopped_because == "parse_error":
        return Verdict(
            passed=False,
            reason=f"run ended on an unhandled parse error: {escaped}",
            details=[
                "no retry was attempted (retry_on_parse_error is false)",
                "a tool returned unparseable JSON and the agent had no recovery path",
            ],
            failure_type="parse_error",
            metrics=metrics,
        )

    expected = float(task["expected_answer"])
    got = _numbers_in(result.answer)
    if round(expected, 2) not in got:
        return Verdict(
            passed=False,
            reason=f"run did not recover to the known value {expected:,.2f}",
            details=[f"answer was: {(result.answer or '(none)')[:200]}"],
            failure_type="parse_error",
            metrics=metrics,
        )

    return Verdict(
        passed=True,
        reason=f"survived the malformed payload and still answered {expected:,.2f}",
        metrics={**metrics, "expected": expected, "recovered": bool(escaped)},
    )


def check_loop(task: dict, result) -> Verdict:
    """Finishes within max_steps_allowed WITH a final answer."""
    limit = int(task["max_steps_allowed"])
    metrics = {"steps": len(result.steps), "max_steps_allowed": limit}

    if not result.answer.strip():
        return Verdict(
            passed=False,
            reason="agent never produced a final answer",
            details=[f"stopped because: {result.stopped_because}"],
            failure_type="loop",
            metrics=metrics,
        )
    if len(result.steps) > limit:
        return Verdict(
            passed=False,
            reason=f"used {len(result.steps)} steps, over the limit of {limit}",
            details=[f"stopped because: {result.stopped_because}"],
            failure_type="loop",
            metrics=metrics,
        )

    expected = float(task["expected_answer"])
    if round(expected, 2) not in _numbers_in(result.answer):
        return Verdict(
            passed=False,
            reason=f"finished under the step limit but the answer is wrong ({expected:,.2f} expected)",
            details=[f"answer was: {result.answer[:200]}"],
            failure_type="loop",
            metrics=metrics,
        )

    return Verdict(
        passed=True,
        reason=f"answered in {len(result.steps)} steps (limit {limit})",
        metrics={**metrics, "expected": expected},
    )


def check_hallucinated_citation(task: dict, result) -> Verdict:
    """Every cited URL must appear in a fetch_page result FROM THIS RUN."""
    metrics = {"steps": len(result.steps)}

    cited = cited_urls_in(result.answer or "")
    fetched = _fetched_urls(result)
    metrics["cited"] = len(cited)
    metrics["fetched"] = len(fetched)

    invented = sorted(cited - fetched)
    if invented:
        return Verdict(
            passed=False,
            reason=f"{len(invented)} cited URL(s) were never fetched",
            details=[f"cited but not fetched: {u}" for u in invented],
            failure_type="hallucinated_citation",
            metrics=metrics,
        )

    return Verdict(
        passed=True,
        reason=f"all {len(cited)} cited URL(s) came from fetch_page in this run",
        metrics=metrics,
    )


CHECKS = {
    "wrong_args": check_wrong_args,
    "parse_error": check_parse_error,
    "loop": check_loop,
    "hallucinated_citation": check_hallucinated_citation,
}


def run_checks(bug: str, task: dict, result) -> Verdict:
    fn = CHECKS.get(bug)
    if fn is None:
        return Verdict(passed=False, reason=f"no check implemented for bug {bug!r}")
    try:
        return fn(task, result)
    except Exception as exc:  # a broken check must not read as a green run
        return Verdict(
            passed=False,
            reason=f"the CHECK ITSELF raised {type(exc).__name__}: {exc}",
            failure_type="other",
        )


def to_json(verdict: Verdict) -> str:
    return json.dumps(verdict.to_dict(), indent=2)","path":"/home/ubuntu/medic/checks/checks.py"}

{"content":""""Task loading.

Tasks are a YAML multi-document stream; each doc is one task. `train.yaml` is the
single task a bug is diagnosed against; `heldout.yaml` holds the unseen ones.

The held-out tasks are loadable but must never be handed to diagnose/surgeon —
a fix that only works on the train task has overfitted, and overfitting is the
one failure mode this project cannot have.
"""
from __future__ import annotations

from typing import Iterator

import yaml

from patient.config import ROOT

TRAIN = ROOT / "tasks" / "train.yaml"
HELDOUT = ROOT / "tasks" / "heldout.yaml"

BUGS = ["wrong_args", "parse_error", "loop", "hallucinated_citation"]


def _load_all(path) -> list[dict]:
    with open(path) as fh:
        return [doc for doc in yaml.safe_load_all(fh) if doc]


def all_tasks() -> list[dict]:
    return _load_all(TRAIN) + _load_all(HELDOUT)


def tasks_for(bug: str, split: str = "train") -> list[dict]:
    path = TRAIN if split == "train" else HELDOUT
    return [t for t in _load_all(path) if t.get("bug") == bug]


def train_task_for(bug: str) -> dict | None:
    found = tasks_for(bug, "train")
    return found[0] if found else None


def heldout_for(bug: str) -> list[dict]:
    return tasks_for(bug, "heldout")


def validate() -> list[str]:
    """Structural check of both files. A malformed task file must fail loudly
    here rather than as a confusing hard-check failure three phases later."""
    problems: list[str] = []
    required = {"id", "bug", "question", "expected_answer", "max_steps_allowed"}
    seen: set[str] = set()

    for path, split in ((TRAIN, "train"), (HELDOUT, "heldout")):
        if not path.exists():
            problems.append(f"missing {split} file: {path}")
            continue
        for i, task in enumerate(_load_all(path), 1):
            missing = required - set(task)
            if missing:
                problems.append(f"{path.name} doc {i}: missing {sorted(missing)}")
                continue
            if task["bug"] not in BUGS:
                problems.append(f"{path.name} doc {i}: unknown bug {task['bug']!r}")
            if task["id"] in seen:
                problems.append(f"{path.name} doc {i}: duplicate id {task['id']!r}")
            seen.add(task["id"])
            if not isinstance(task["max_steps_allowed"], int):
                problems.append(f"{path.name} doc {i}: max_steps_allowed must be an int")

    for bug in BUGS:
        if not tasks_for(bug, "train"):
            problems.append(f"no TRAIN task for bug {bug}")
        if len(heldout_for(bug)) < 2:
            problems.append(
                f"bug {bug} has {len(heldout_for(bug))} held-out task(s); spec wants 2-3"
            )
    return problems


if __name__ == "__main__":
    issues = validate()
    if issues:
        for p in issues:
            print(f"PROBLEM: {p}")
        raise SystemExit(1)
    print(f"tasks OK: {len(all_tasks())} total")
    for bug in BUGS:
        print(f"  {bug}: 1 train, {len(heldout_for(bug))} held-out")","path":"/home/ubuntu/medic/tasks/loader.py"}

{"content":""""A deterministic, offline stand-in for the LLM.

It is NOT a dumb mock. It READS medic.yaml and behaves the way a literal,
obedient model would given that configuration:

  * calculator description is vague  -> passes PROSE instead of an expression
  * system prompt has no stop rule   -> keeps searching past the budget
  * prompt says "cite what you know" -> cites a URL it never fetched
  * retry_on_parse_error is true     -> re-asks after a malformed payload

That is the whole point: the SAME loop then fails or passes purely because of
a config change, which is exactly what Medic is supposed to fix. A mock that
ignored the config would make every bug fake, and the demo would prove nothing.

Deterministic by construction: no randomness, no clock, no network. The same
config always produces the same run — which is what "heal it twice in a row"
requires.
"""
from __future__ import annotations

import json
import re
import types


class _Msg:
    def __init__(self, content=None, tool_calls=None):
        self.role = "assistant"
        self.content = content
        self.tool_calls = tool_calls

    def model_dump(self, exclude_none=True):
        d: dict = {"role": "assistant", "content": self.content}
        if self.tool_calls:
            d["tool_calls"] = [
                {
                    "id": t.id,
                    "type": "function",
                    "function": {"name": t.function.name, "arguments": t.function.arguments},
                }
                for t in self.tool_calls
            ]
        return d


class _Fn:
    def __init__(self, name, arguments):
        self.name = name
        self.arguments = arguments


class _Call:
    def __init__(self, name, arguments, i):
        self.id = f"call_{i}"
        self.function = _Fn(name, arguments)


def _resp(msg):
    usage = types.SimpleNamespace(prompt_tokens=120, completion_tokens=35)
    return types.SimpleNamespace(choices=[types.SimpleNamespace(message=msg)], usage=usage)


# A URL that is NOT in any fixture — inventing it is the bug-4 failure.
INVENTED_URL = "https://widget-facts.example.org/pricing-2024"

# query -> fixture key. The scripted agent can only find what we stored.
QUERY_TABLE = {
    "widget price": "widget price",
    "widget bulk discount": "widget bulk discount",
    "acme widget order": "acme widget order",
    "blue gadget price": "blue gadget price",
    "orbit server price": "orbit server price",
    "helio panel price": "helio panel price",
}


class ScriptedLLM:
    """OpenAI-shaped client. Injected wherever a real one would go."""

    def __init__(self, config: dict | None = None):
        self.config = config or {}
        prompt = str(self.config.get("system_prompt", ""))
        calc_desc = str(
            (self.config.get("tools") or {}).get("calculator", {}).get("description", "")
        )

        # ── read the config the way a literal model would ──
        self.max_searches = 6 if _lacks_stop_rule(prompt) else 2
        self.emit_prose = _vague(calc_desc)
        self.cite_without_evidence = "cite what you know" in prompt.lower()
        self.retry_allowed = bool(self.config.get("retry_on_parse_error", False))

        self.searches = 0
        self.fetched: list[str] = []
        self.invented = False
        self.retried_after_parse_error = False
        self._calls = 0
        self.chat = types.SimpleNamespace(completions=self)

    # ── OpenAI surface ──────────────────────────────────────────────────
    def create(self, **kwargs):
        self._calls += 1
        messages = kwargs.get("messages", [])

        # A user turn asking for a single JSON object = a retry after a parse
        # error. Honouring it is exactly what retry_on_parse_error buys.
        last_user = next(
            (m for m in reversed(messages) if m.get("role") == "user"), {}
        ).get("content", "")
        if "not valid JSON" in str(last_user):
            self.retried_after_parse_error = True
            return _resp(
                _Msg(tool_calls=[_Call("calculator", json.dumps({"expression": "(128.40*250)*(1-0.12)"}), self._calls)])
            )

        last = next((m for m in reversed(messages) if m.get("role") == "tool"), None)
        if last is None:
            return self._first_search(messages)

        try:
            payload = json.loads(last["content"])
        except json.JSONDecodeError:
            return _resp(_Msg(content="I could not read that tool output."))

        if "results" in payload:
            return self._on_search_results(payload, messages)
        if "text" in payload:
            return self._on_page(payload.get("text", ""), payload.get("url", ""))
        return self._final()

    # ── behaviour ───────────────────────────────────────────────────────
    def _first_search(self, messages):
        query = self._query_for(messages)
        return self._search(query)

    def _search(self, query):
        self.searches += 1
        return _resp(_Msg(tool_calls=[_Call("web_search", json.dumps({"query": query}), self._calls)]))

    def _on_search_results(self, payload, messages):
        results = payload.get("results") or []
        if not results:
            if self.searches < self.max_searches:
                return self._search(self._query_for(messages, alt=True))
            return self._final()
        url = results[0]["url"]
        if url not in self.fetched:
            self.fetched.append(url)
            return _resp(
                _Msg(tool_calls=[_Call("fetch_page", json.dumps({"url": url}), self._calls)])
            )
        return self._final()

    def _on_page(self, text: str, url: str):
        expr = _expression_for(text)
        if expr is None:
            return self._final()
        if self.emit_prose:
            # The bug: prose where an expression belongs.
            return _resp(
                _Msg(
                    tool_calls=[
                        _Call("calculator", "the unit price times the quantity minus twelve percent", self._calls)
                    ]
                )
            )
        return _resp(
            _Msg(tool_calls=[_Call("calculator", json.dumps({"expression": expr}), self._calls)])
        )

    def _final(self):
        expr_note = ""
        if self.emit_prose:
            expr_note = " (I was unable to compute it precisely.)"
        if self.cite_without_evidence and not self.invented:
            self.invented = True
            return _resp(
                _Msg(
                    content=(
                        f"The total is $28,250.00.{expr_note} "
                        f"See {INVENTED_URL} for the underlying figures."
                    )
                )
            )
        cited = self.fetched[0] if self.fetched else ""
        return _resp(
            _Msg(
                content=(
                    f"The total is $28,250.00.{expr_note} "
                    + (f"Source: {cited}" if cited else "")
                )
            )
        )

    def _query_for(self, messages, alt: bool = False) -> str:
        text = " ".join(str(m.get("content", "")) for m in messages).lower()
        ordered = [
            ("250 widget", "widget price", "acme widget order"),
            ("gadget", "blue gadget price", "orbit server price"),
            ("case", "blue gadget price", "widget price"),
            ("server", "orbit server price", "blue gadget price"),
            ("panel", "helio panel price", "widget price"),
            ("solar", "helio panel price", "widget price"),
            ("unit", "widget price", "blue gadget price"),
            ("re-price", "widget price", "acme widget order"),
            ("widget", "widget price", "acme widget order"),
        ]
        for key, first, second in ordered:
            if key in text:
                return second if alt else first
        return "orbit server price" if alt else "widget price"


# ── config-reading helpers (the whole point of this module) ──────────────
def _lacks_stop_rule(prompt: str) -> bool:
    low = prompt.lower()
    has_stop = any(
        phrase in low
        for phrase in ("stop rule", "as soon as you can answer", "stop calling tools", "never make more than")
    )
    return not has_stop


def _vague(description: str) -> bool:
    """A description that never shows an example cannot pin the arg format."""
    low = description.lower()
    return not any(token in low for token in ("expression", "e.g", "example", "plain arithmetic"))


def _expression_for(text: str) -> str | None:
    if not text:
        return None
    if "128.40" in text and "12%" in text:
        return "(128.40*250)*(1-0.12)"
    if "1,250.00" in text:
        return "1250*4"
    if "450.00" in text:
        return "450.00*3"
    if "79.99" in text:
        return "79.99*2"
    if "128.40" in text:
        return "128.40*250"
    return None


def extract_numbers(text: str) -> list[float]:
    return [float(x.replace(",", "")) for x in re.findall(r"-?[\d,]+\.?\d*", text)]","path":"/home/ubuntu/medic/patient/scripted.py"}

