    """The expression implied by a fetched page's contents."""
    if not text:
        return None
    if "128.40" in text and "12%" in text:
        return "(128.40*250)*(1-0.12)"
    if "1,250.00" in text:
        return "1250*4"
    if "450.00" in text:
        return "450.00*3"
    if "79.99" in text:
        return "79.99*2"
    if "128.40" in text:
        return "128.40*250"
    return None


def extract_numbers(text: str) -> list[float]:
    return [float(x.replace(",", "")) for x in re.findall(r"-?[\d,]+\.?\d*", text)]","path":"/home/ubuntu/medic/patient/scripted.py"}

